import { useCallback, useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

export type ReportDatePickerProps = {
  defaultValue?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];

const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());

const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);

const isSameDay = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();

function buildMonthGrid(month: Date): Date[] {
  const first = new Date(month.getFullYear(), month.getMonth(), 1);
  const mondayOffset = (first.getDay() + 6) % 7;
  const start = addDays(first, -mondayOffset);
  return Array.from({ length: 42 }, (_, i) => addDays(start, i));
}

export default function ReportDatePicker({ defaultValue, onChange }: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [selected, setSelected] = useState<Date>(() => startOfDay(defaultValue ?? new Date()));
  const [month, setMonth] = useState<Date>(
    () => new Date(selected.getFullYear(), selected.getMonth(), 1),
  );

  const select = useCallback(
    (date: Date) => {
      const day = startOfDay(date);
      setSelected(day);
      setMonth(new Date(day.getFullYear(), day.getMonth(), 1));
      onChange(day);
    },
    [onChange],
  );

  const days = useMemo(() => buildMonthGrid(month), [month]);

  const presets = useMemo(
    () => [
      { label: 'Сегодня', date: today },
      { label: 'Вчера', date: addDays(today, -1) },
      { label: 'Неделя назад', date: addDays(today, -7) },
    ],
    [today],
  );

  const monthTitle = month.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' });

  return (
    <section
      className="jx-card jx-stack"
      aria-label="Дата отчёта"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4, 16px)',
        padding: 'var(--jx-space-4, 16px)',
        borderRadius: 'var(--jx-radius, 4px)',
      }}
    >
      <div
        className="jx-row"
        role="group"
        aria-label="Быстрый выбор"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2, 8px)' }}
      >
        {presets.map((preset) => (
          <Button
            key={preset.label}
            type="button"
            size="sm"
            variant={isSameDay(preset.date, selected) ? 'primary' : 'ghost'}
            aria-pressed={isSameDay(preset.date, selected)}
            onClick={() => select(preset.date)}
          >
            {preset.label}
          </Button>
        ))}
      </div>

      <div
        className="jx-row"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-2, 8px)',
        }}
      >
        <Button
          type="button"
          size="sm"
          variant="ghost"
          aria-label="Предыдущий месяц"
          onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))}
        >
          ←
        </Button>
        <span className="jx-text" aria-live="polite">
          {monthTitle}
        </span>
        <Button
          type="button"
          size="sm"
          variant="ghost"
          aria-label="Следующий месяц"
          onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))}
        >
          →
        </Button>
      </div>

      <div
        className="jx-grid"
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(7, minmax(0, 1fr))',
          gap: 'var(--jx-space-1, 4px)',
        }}
      >
        {WEEKDAYS.map((weekday) => (
          <span
            key={weekday}
            className="jx-text jx-text--muted"
            aria-hidden="true"
            style={{ textAlign: 'center', fontSize: 'var(--jx-font-size-sm, 12px)' }}
          >
            {weekday}
          </span>
        ))}

        {days.map((day) => {
          const inMonth = day.getMonth() === month.getMonth();
          const isSelected = isSameDay(day, selected);
          const classes = ['jx-btn', 'jx-btn--sm', isSelected ? 'jx-btn--primary' : 'jx-btn--ghost'];
          if (!inMonth) classes.push('jx-text--muted');

          return (
            <button
              key={day.toISOString()}
              type="button"
              className={classes.join(' ')}
              aria-pressed={isSelected}
              aria-current={isSameDay(day, today) ? 'date' : undefined}
              aria-label={day.toLocaleDateString('ru-RU', {
                day: 'numeric',
                month: 'long',
                year: 'numeric',
              })}
              onClick={() => select(day)}
              style={{ width: '100%', borderRadius: 'var(--jx-radius, 4px)' }}
            >
              {day.getDate()}
            </button>
          );
        })}
      </div>
    </section>
  );
}

